<?php
declare(strict_types=1);ob_start();session_start();require dirname(__DIR__,2).'/config/config.php';require_once dirname(__DIR__).'/lib/school_sms.php';
function ann_json(int $status,array $data):never{http_response_code($status);header('Content-Type: application/json; charset=utf-8');header('Cache-Control: no-store');if(ob_get_level())ob_clean();echo json_encode($data,JSON_THROW_ON_ERROR|JSON_UNESCAPED_UNICODE);exit;}
function ann_ok(string $message,array $data=[]):never{ann_json(200,['ok'=>true,'message'=>$message,'data'=>$data]);}
if(!signed_in())ann_json(401,['ok'=>false,'message'=>'Your session expired. Sign in again.']);require_sign_in();if(!empty($_SESSION['must_change_password']))ann_json(403,['ok'=>false,'message'=>'Change your password before continuing.']);
$role=(string)$_SESSION['role'];$roles=['admin','director','sub_director','headteacher','head_academic'];if(!in_array($role,$roles,true))ann_json(403,['ok'=>false,'message'=>'Your role cannot manage announcements.']);$uid=(int)$_SESSION['user_id'];$school=filter_var($_REQUEST['school_id']??null,FILTER_VALIDATE_INT);if(!$school)ann_json(422,['ok'=>false,'message'=>'Choose a school.']);$db=db();$q=$db->prepare('SELECT 1 FROM school_memberships WHERE user_id=? AND school_id=?');$q->execute([$uid,$school]);if(!$q->fetchColumn())ann_json(403,['ok'=>false,'message'=>'That school is outside your access.']);
if($_SERVER['REQUEST_METHOD']==='GET'){$q=$db->prepare('SELECT id,title,body,audience,status,expires_at,published_at,created_at FROM school_announcements WHERE school_id=? ORDER BY created_at DESC LIMIT 200');$q->execute([$school]);ann_ok('Announcements loaded.',['announcements'=>$q->fetchAll()]);}
if($_SERVER['REQUEST_METHOD']!=='POST')ann_json(405,['ok'=>false,'message'=>'Method not allowed.']);if(!hash_equals($_SESSION['csrf']??'',(string)($_SERVER['HTTP_X_CSRF_TOKEN']??$_POST['csrf']??'')))ann_json(400,['ok'=>false,'message'=>'Your session expired. Refresh and try again.']);$action=(string)($_POST['action']??'');
try{
 if($action==='create'){$title=trim((string)($_POST['title']??''));$body=trim((string)($_POST['body']??''));$audience=(string)($_POST['audience']??'all');$expires=trim((string)($_POST['expires_at']??''));if($title===''||mb_strlen($title)>180||$body===''||mb_strlen($body)>30000||!in_array($audience,['all','parents','pupils','staff'],true)||($expires!==''&&(!preg_match('/^\d{4}-\d{2}-\d{2}$/',$expires)||!checkdate((int)substr($expires,5,2),(int)substr($expires,8,2),(int)substr($expires,0,4)))))throw new DomainException('Enter a title, announcement text, audience, and valid optional expiry date.');$db->beginTransaction();$q=$db->prepare("INSERT INTO school_announcements(school_id,title,body,audience,status,expires_at,created_by) VALUES(?,?,?,?, 'draft',?,?)");$q->execute([$school,$title,$body,$audience,$expires?:null,$uid]);$id=(int)$db->lastInsertId();$q=$db->prepare('INSERT INTO audit_logs(actor_id,action,entity_type,entity_id,details) VALUES(?,?,?,?,?)');$q->execute([$uid,'create','school_announcement',$id,json_encode(['school_id'=>$school,'audience'=>$audience,'expires_at'=>$expires?:null],JSON_THROW_ON_ERROR)]);$db->commit();ann_ok('Announcement draft saved.',['id'=>$id]);}
 if($action==='publish'){$id=(int)($_POST['announcement_id']??0);$db->beginTransaction();$q=$db->prepare("SELECT id,status,expires_at FROM school_announcements WHERE id=? AND school_id=? FOR UPDATE");$q->execute([$id,$school]);$a=$q->fetch();if(!$a||$a['status']!=='draft')throw new DomainException('Only a draft announcement can be published.');if($a['expires_at']!==null&&$a['expires_at']<date('Y-m-d'))throw new DomainException('This announcement expiry date has passed. Update its expiry before publishing.');$q=$db->prepare("UPDATE school_announcements SET status='published',published_by=?,published_at=CURRENT_TIMESTAMP WHERE id=? AND school_id=? AND status='draft'");$q->execute([$uid,$id,$school]);$q=$db->prepare('INSERT INTO audit_logs(actor_id,action,entity_type,entity_id,details) VALUES(?,?,?,?,?)');$q->execute([$uid,'publish','school_announcement',$id,json_encode(['school_id'=>$school],JSON_THROW_ON_ERROR)]);queue_school_announcement_sms($db,$school,$id,$uid);$db->commit();ann_ok('Announcement published to its selected audience.',['id'=>$id]);}
 if($action==='archive'){$id=(int)($_POST['announcement_id']??0);$db->beginTransaction();$q=$db->prepare("SELECT id,status FROM school_announcements WHERE id=? AND school_id=? FOR UPDATE");$q->execute([$id,$school]);$a=$q->fetch();if(!$a||$a['status']==='archived')throw new DomainException('Announcement not found or already archived.');$db->prepare("UPDATE school_announcements SET status='archived' WHERE id=? AND school_id=?")->execute([$id,$school]);$q=$db->prepare('INSERT INTO audit_logs(actor_id,action,entity_type,entity_id,details) VALUES(?,?,?,?,?)');$q->execute([$uid,'archive','school_announcement',$id,json_encode(['school_id'=>$school,'previous_status'=>$a['status']],JSON_THROW_ON_ERROR)]);$db->commit();ann_ok('Announcement archived.');}
 throw new DomainException('Choose a supported announcement action.');
}catch(DomainException $e){if($db->inTransaction())$db->rollBack();ann_json(422,['ok'=>false,'message'=>$e->getMessage()]);}catch(PDOException $e){if($db->inTransaction())$db->rollBack();error_log('Announcement database error: '.$e->getMessage());ann_json(500,['ok'=>false,'message'=>'The announcement could not be saved. Verify its migration.']);}catch(Throwable $e){if($db->inTransaction())$db->rollBack();error_log('Announcement request error: '.$e->getMessage());ann_json(500,['ok'=>false,'message'=>'The announcement request could not be completed.']);}
